"""The container under test, live (plan D8, D20, T1.5). Needs Docker, needs no Gramps.

Tool registration happens at import time and the REST client is lazy, so the handshake and
the tool list answer without any instance behind them. That makes this the cheapest possible
test of the layer that has actually shipped broken twice:

* a root module missing from the Dockerfile's explicit `COPY` list builds fine and crashes on
  import — here that is a handshake that never completes;
* the destructive gate is structural, so `off 27 / on 31` is the property, not a setting. The
  release ritual checks it by hand every wave; this checks it on the image under test.
"""

from __future__ import annotations

from collections.abc import Iterator

import pytest
from harness.docker_util import docker, resource_exists
from harness.mcp_container import ImageRef, McpContainer, container_name

TOOLS_WITHOUT_DESTRUCTIVE = 27
TOOLS_WITH_DESTRUCTIVE = 31

ENV = {
    "GRAMPS_BASE_URL": "http://gwe2e-nowhere:5000",
    "GRAMPS_USERNAME": "nobody",
    "GRAMPS_PASSWORD": "unused",
}


def all_tools(mcp: McpContainer) -> list[str]:
    """Follow `nextCursor` — the list is paginated and a single page is not the whole gate."""
    names, cursor = [], None
    while True:
        page = mcp.list_tools(cursor)
        names += [tool["name"] for tool in page.get("tools", [])]
        cursor = page.get("nextCursor")
        if not cursor:
            return names


def spawn(image: ImageRef, runid: str, label: str, env: dict[str, str]) -> McpContainer:
    return McpContainer(
        container_name(runid, label), image.run_reference, env, runid=runid, network="none"
    )


@pytest.fixture(scope="module")
def mcp(mcp_image: ImageRef, e2e_runid: str) -> Iterator[McpContainer]:
    running = spawn(mcp_image, e2e_runid, "gate-off", ENV)
    try:
        yield running
    finally:
        assert running.close() == [], "the MCP container outlived its test"


def test_the_image_under_test_completes_the_handshake(mcp: McpContainer) -> None:
    """If a module is missing from the COPY list, the server dies here and nowhere else."""
    reply = mcp.start() and mcp.initialize_reply
    assert reply is not None
    assert reply["result"]["serverInfo"]["name"]


def test_without_the_flag_the_destructive_tools_do_not_exist(mcp: McpContainer) -> None:
    names = all_tools(mcp)

    assert len(names) == TOOLS_WITHOUT_DESTRUCTIVE
    assert not [name for name in names if name.startswith("gramps_delete_")]


def test_one_container_serves_every_request_of_a_test(mcp: McpContainer) -> None:
    """Reuse is not a detail: a container per call is a start and a token mint per call."""
    before = docker("inspect", mcp.name, "--format", "{{.Id}}")
    for _ in range(3):
        assert all_tools(mcp)

    assert docker("inspect", mcp.name, "--format", "{{.Id}}") == before


def test_with_the_flag_the_destructive_tools_are_registered(
    mcp_image: ImageRef, e2e_runid: str
) -> None:
    """The other half of the structural gate, on the image that would actually ship."""
    armed = spawn(mcp_image, e2e_runid, "gate-on", {**ENV, "GRAMPS_ENABLE_DESTRUCTIVE": "1"})
    try:
        names = all_tools(armed)
    finally:
        assert armed.close() == []

    assert len(names) == TOOLS_WITH_DESTRUCTIVE
    assert "gramps_delete_all_objects" in names


def test_closing_actually_removes_the_container(mcp_image: ImageRef, e2e_runid: str) -> None:
    """`--rm` is a promise about a clean exit, not a teardown — so the teardown looks."""
    running = spawn(mcp_image, e2e_runid, "closes", ENV)
    running.start()
    assert resource_exists("container", running.name)

    assert running.close() == []
    assert not resource_exists("container", running.name)
